import math

def check_cube(n):
    if n < 0:
        return None
    if n == 0:
        return 0

    # Estimate the cube root
    root = round(n**(1/3))

    # Check if it's a perfect cube
    if root**3 == n:
        return root
    return None

# Test small primes q
primes = [2, 3, 5, 7, 11, 13]
results = {}
for q in primes:
    val = q*q - q + 1
    p = check_cube(val)
    results[q] = (val, p)

print(results)

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_perfect_cube(n):
    if n < 0:
        return None
    # Use round for precision since floating point cube root can be slightly off
    root = round(n**(1/3))
    if root**3 == n:
        return root
    return None

def check_primes_up_to(limit):
    primes = []
    for num in range(2, limit + 1):
        if is_prime(num):
            primes.append(num)

    results = []
    print(f"Checking primes q up to {limit}: {primes}\n")

    for q in primes:
        N = q*q - q + 1
        p = is_perfect_cube(N)

        if p is not None:
            if is_prime(p) and p != q:
                results.append((q, p, N))

        print(f"q={q}: q^2 - q + 1 = {N}. Perfect cube? {p is not None}. p={p} (prime and p!=q: {p is not None and is_prime(p) and p != q})")

    return results

# Run the check for primes up to 50
solutions = check_primes_up_to(50)

print("\n--- Final Results ---")
if solutions:
    print("Found solutions (q, p):")
    for q, p, N in solutions:
        print(f"q = {q} yields N = {N} = {p}^3. p = {p} is prime and p != q.")
else:
